59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /** Dedicated audit logger for owner lifecycle side-effects. */
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    /**
72	     * Pragmatic check for a syntactically valid email address: a non-empty local
73	     * part, a single '@', and a domain with at least one dot-separated label.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
77	
78	    /**
79	     * Disposable email domains that are rejected: an owner email whose domain is one of
80	     * these is treated as invalid so the create/update is rejected with 400. Compared
81	     * case-insensitively against the normalized (lower-cased) email domain.
82	     */
83	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
84	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
85	
86	    /**
87	     * Common street-type abbreviations expanded during address normalization,
88	     * keyed by their upper-cased form.
89	     */
90	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
91	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
92	
93	    /**
94	     * Required national-number length keyed by E.164 country calling code: a
95	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
96	     * (NANP) number carries 10. A number whose country code is listed here must have
97	     * exactly the mandated number of national digits.
98	     */
99	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
100	        Map.of("61", 9, "1", 10);
101	
102	    /**
103	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by the region derived
104	     * from the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose
105	     * region is not listed here (see {@link OwnerMapper#CITY_REGION}) accepts any 4-digit
106	     * postcode.
107	     */
108	    private static final Map<String, int[]> REGION_POSTCODE_RANGES =
109	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
110	            "QLD", new int[] {4000, 4099});
111	
112	    private final ClinicService clinicService;
113	
114	    private final OwnerMapper ownerMapper;
115	
116	    private final PetMapper petMapper;
117	
118	    private final VisitMapper visitMapper;
119	
120	    public OwnerRestControllerV1(ClinicService clinicService,
121	                                 OwnerMapper ownerMapper,
122	                                 PetMapper petMapper,
123	                                 VisitMapper visitMapper) {
124	        this.clinicService = clinicService;
125	        this.ownerMapper = ownerMapper;
126	        this.petMapper = petMapper;
127	        this.visitMapper = visitMapper;
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
133	        Collection<Owner> owners;
134	        if (lastName != null) {
135	            owners = this.clinicService.findOwnerByLastName(lastName);
136	        } else {
137	            owners = this.clinicService.findAllOwners();
138	        }
139	        if (owners.isEmpty()) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
158	        // Validate & normalize the optional email; reject the create when it is present but invalid.
159	        if (!normalizeEmail(ownerFieldsDto)) {
160	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	        }
162	        // Validate & normalize the optional postcode; reject the create when it is present but
163	        // not valid for the owner's city (see normalizePostcode).
164	        if (!normalizePostcode(ownerFieldsDto)) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
168	        // abbreviations) and store the normalized form back on the DTO so it is what gets
169	        // persisted and compared. Reject the create when the address is blank once normalized.
170	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
171	        if (canonicalAddress.isBlank()) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        ownerFieldsDto.setAddress(canonicalAddress);
175	        // Reject the create when the owner's city is already at capacity, i.e. it already
176	        // contains 50 or more owners (compared case-insensitively).
177	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
178	            return new ResponseEntity<>(HttpStatus.CONFLICT);
179	        }
180	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
181	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
182	        if (normalizedTelephone == null) {
183	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	        }
185	        ownerFieldsDto.setTelephone(normalizedTelephone);
186	        // Consolidated duplicate detection. All former separate telephone, email and household
187	        // duplicate checks are now expressed through the single derived identity key
188	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
189	        // A create is rejected only when the new owner's identity collides with an existing owner's.
190	        // Because the telephone is part of the identity, two members of the same household with
191	        // different telephones no longer collide and are both allowed; only owners that share the
192	        // same normalized telephone and email are treated as the same identity.
193	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
194	        String contactIdentity = identityContact(candidate);
195	        boolean identityInUse = this.clinicService.findAllOwners().stream()
196	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
197	        if (identityInUse) {
198	            return new ResponseEntity<>(HttpStatus.CONFLICT);
199	        }
200	        // Household duplicate detection keyed on the deterministic householdId, derived from the
201	        // normalized last name and postcode (see OwnerMapper#householdId). Owners sharing a last
202	        // name and postcode share the same household. A second owner in an existing household is
203	        // rejected as a household duplicate (409) unless the request declares 'sharesHousehold',
204	        // in which case it is created as a declared household member — 'sharesHousehold' only
205	        // bypasses this block; the household link itself now follows from the computed householdId.
206	        String householdId = ownerMapper.householdId(candidate);
207	        boolean householdExists = this.clinicService.findAllOwners().stream()
208	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
209	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
210	        if (householdExists && !sharesHousehold) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        boolean declaredMember = householdExists && sharesHousehold;
214	        // Determine the effective registration date — the value supplied on the request, or the
215	        // server's current date when none was supplied — and roll it forward to the next business
216	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
217	        // registration date (membership-number year segment, per-day create-limit) uses this
218	        // adjusted date.
219	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
220	        if (registrationDate == null) {
221	            registrationDate = LocalDate.now();
222	        }
223	        // Reject a supplied registration date that lies in the future (later than the
224	        // server's current date): an owner cannot be registered ahead of time.
225	        else if (registrationDate.isAfter(LocalDate.now())) {
226	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
227	        }
228	        registrationDate = toBusinessDay(registrationDate);
229	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
230	        // owners have already been registered on this (adjusted) business day.
231	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
232	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
233	        }
234	        HttpHeaders headers = new HttpHeaders();
235	        Owner owner = candidate;
236	        owner.setRegistrationDate(registrationDate);
237	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
238	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
239	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
240	        owner.setCustomerCode(customerCode(owner));
241	        // Record how many existing owners already share this owner's first and last name
242	        // (compared case-insensitively) at the moment before this owner is created.
243	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
244	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
245	        // registered on this (adjusted) business day before this owner is created.
246	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
247	        // Record the size of this owner's household after this create: the number of existing
248	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
249	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
250	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate, but it
251	        // shares an existing owner's last name (case-insensitively) and postcode while carrying a
252	        // different telephone. When such a match exists, record it as 'possibleDuplicate' with
253	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
254	        // duplicate. A declared household member is an acknowledged member, not a suspected
255	        // duplicate, so it is never flagged.
256	        if (declaredMember) {
257	            owner.setPossibleDuplicate(false);
258	            owner.setPossibleDuplicateOf(null);
259	        }
260	        else {
261	            Owner softMatch = findPossibleDuplicate(owner);
262	            owner.setPossibleDuplicate(softMatch != null);
263	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
264	        }
265	        this.clinicService.saveOwner(owner);
266	        // Emit an audit line recording the new owner's id, customer code, registration date,
267	        // membership level and membership number.
268	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
269	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
270	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
271	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
272	        headers.setLocation(UriComponentsBuilder.newInstance()
273	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
274	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
275	    }
276	
277	    /**
278	     * Validate and normalize the optional owner email in place.
279	     *
280	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
281	     * When present it must be a syntactically valid address; a valid address is
282	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
283	     * present but syntactically invalid, so the caller can reject with 400.
284	     */
285	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
286	        String email = ownerFieldsDto.getEmail();
287	        if (email == null || email.isBlank()) {
288	            ownerFieldsDto.setEmail(null);
289	            return true;
290	        }
291	        String normalized = email.trim().toLowerCase(Locale.ROOT);
292	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
293	            return false;
294	        }
295	        // Reject addresses whose domain is on the disposable-domain blocklist.
296	        String domain = normalized.substring(normalized.indexOf('@') + 1);
297	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
298	            return false;
299	        }
300	        ownerFieldsDto.setEmail(normalized);
301	        return true;
302	    }
303	
304	    /**
305	     * Validate the optional owner postcode in place.
306	     *
307	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
308	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
309	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
310	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
311	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
312	     * when a postcode is present but malformed or out of range, so the caller can
313	     * reject with 400.
314	     */
315	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
316	        String postcode = ownerFieldsDto.getPostcode();
317	        if (postcode == null || postcode.isBlank()) {
318	            ownerFieldsDto.setPostcode(null);
319	            return true;
320	        }
321	        if (!postcode.matches("\\d{4}")) {
322	            return false;
323	        }
324	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
325	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
326	        if (range != null) {
327	            int value = Integer.parseInt(postcode);
328	            if (value < range[0] || value > range[1]) {
329	                return false;
330	            }
331	        }
332	        return true;
333	    }
334	
335	    /**
336	     * Normalize an owner address: trim, collapse each run of whitespace to a single
337	     * space, upper-case, and expand common street-type abbreviations
338	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
339	     * A {@code null} value normalizes to the empty string.
340	     */
341	    private static String normalizeAddress(String value) {
342	        if (value == null) {
343	            return "";
344	        }
345	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
346	        if (collapsed.isEmpty()) {
347	            return "";
348	        }
349	        String[] tokens = collapsed.split(" ");
350	        StringBuilder sb = new StringBuilder(collapsed.length());
351	        for (int i = 0; i < tokens.length; i++) {
352	            if (i > 0) {
353	                sb.append(' ');
354	            }
355	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
356	        }
357	        return sb.toString();
358	    }
359	
360	    /**
361	     * The contact portion of an owner's derived identity key: its normalized telephone and
362	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
363	     * without the household segment. Two owners share an identity when this value is equal;
364	     * because the telephone is part of it, members of one household with different telephones
365	     * do not collide. A {@code null} email contributes the empty string.
366	     */
367	    private static String identityContact(Owner owner) {
368	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
369	        String email = owner.getEmail() == null ? "" : owner.getEmail();
370	        return telephone + "|" + email;
371	    }
372	
373	    /**
374	     * Normalize a telephone number to E.164 form.
375	     *
376	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
377	     * explicit leading {@code '+'} and country code it is kept; otherwise the
378	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
379	     * dropped from the national digits. The result must contain 8 to 15 digits
380	     * after the {@code '+'}, and — for a recognised country calling code — exactly
381	     * the national-number length that code mandates ({@code '+61'} => 9 national
382	     * digits, {@code '+1'} => 10).
383	     *
384	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
385	     *         the input is absent or cannot form a valid E.164 number.
386	     */
387	    private static String toE164(String raw) {
388	        if (raw == null) {
389	            return null;
390	        }
391	        String trimmed = raw.trim();
392	        boolean hasCountryCode = trimmed.startsWith("+");
393	        // Strip spaces, dashes and brackets.
394	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
395	        String digits;
396	        if (hasCountryCode) {
397	            // Keep the explicit country code; drop the leading '+' for validation.
398	            digits = stripped.substring(1);
399	        } else {
400	            // No country code: assume '+61' and drop a single leading '0'.
401	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
402	            digits = "61" + national;
403	        }
404	        if (!digits.matches("\\d{8,15}")) {
405	            return null;
406	        }
407	        // For a recognised country calling code, enforce the exact national-number length it
408	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
409	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
410	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
411	                .sorted((a, b) -> b.length() - a.length()).toList()) {
412	            if (digits.startsWith(countryCode)) {
413	                int nationalLength = digits.length() - countryCode.length();
414	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
415	                    return null;
416	                }
417	                break;
418	            }
419	        }
420	        return "+" + digits;
421	    }
422	
423	    /**
424	     * Count the existing owners whose first and last name match the given names,
425	     * compared case-insensitively. Used to record an owner's namesake count at the
426	     * moment before it is created.
427	     */
428	    private int countNamesakes(String firstName, String lastName) {
429	        return (int) this.clinicService.findAllOwners().stream()
430	            .filter(existing -> existing.getFirstName() != null
431	                && existing.getFirstName().equalsIgnoreCase(firstName)
432	                && existing.getLastName() != null
433	                && existing.getLastName().equalsIgnoreCase(lastName))
434	            .count();
435	    }
436	
437	    /**
438	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
439	     * computed householdId (derived from the normalized last name and postcode). Used, together
440	     * with the owner being created, to derive the household size recorded on the owner.
441	     */
442	    private int countHouseholdMembers(Owner owner) {
443	        String householdId = ownerMapper.householdId(owner);
444	        return (int) this.clinicService.findAllOwners().stream()
445	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
446	            .count();
447	    }
448	
449	    /**
450	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
451	     * of: one sharing the same last name (compared case-insensitively) and the same postcode, but
452	     * carrying a different normalized telephone. Owners without a postcode never match (the postcode
453	     * must be shared). When several existing owners match, the one with the lowest id is returned so
454	     * the result is deterministic. Returns {@code null} when there is no such match.
455	     */
456	    private Owner findPossibleDuplicate(Owner candidate) {
457	        if (candidate.getPostcode() == null) {
458	            return null;
459	        }
460	        return this.clinicService.findAllOwners().stream()
461	            .filter(existing -> existing.getLastName() != null
462	                && existing.getLastName().equalsIgnoreCase(candidate.getLastName())
463	                && candidate.getPostcode().equals(existing.getPostcode())
464	                && !candidate.getTelephone().equals(existing.getTelephone()))
465	            .min(java.util.Comparator.comparing(Owner::getId))
466	            .orElse(null);
467	    }
468	
469	    /**
470	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
471	     *
472	     * <p>{@code REGION} is the region derived from the owner's postcode (see
473	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
474	     * SHA-256 of the normalized telephone concatenated with the last name
475	     * (e.g. {@code 'NSW-1A2B3C4D'}).
476	     *
477	     * <p>When the computed code collides with an existing owner's customer code, it is
478	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more
479	     * that makes it unique.
480	     */
481	    private String customerCode(Owner owner) {
482	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
483	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
484	        String base = region + "-" + hash8;
485	        Set<String> existing = this.clinicService.findAllOwners().stream()
486	            .map(Owner::getCustomerCode)
487	            .filter(java.util.Objects::nonNull)
488	            .collect(Collectors.toSet());
489	        if (!existing.contains(base)) {
490	            return base;
491	        }
492	        int n = 2;
493	        while (existing.contains(base + "-" + n)) {
494	            n++;
495	        }
496	        return base + "-" + n;
497	    }
498	
499	    /**
500	     * Derive the owner's region, preferring the postcode. The postcode is matched against
501	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
502	     * it is absent or in no known range does this fall back to the fixed city-to-region table
503	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
504	     */
505	    private static String deriveRegion(String postcode, String city) {
506	        if (postcode != null && postcode.matches("\\d{4}")) {
507	            int value = Integer.parseInt(postcode);
508	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
509	                int[] range = entry.getValue();
510	                if (value >= range[0] && value <= range[1]) {
511	                    return entry.getKey();
512	                }
513	            }
514	        }
515	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
516	    }
517	
518	    /**
519	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
520	     * bytes of {@code value}.
521	     */
522	    private static String sha256HexUpper(String value, int length) {
523	        try {
524	            byte[] digest = MessageDigest.getInstance("SHA-256")
525	                .digest(value.getBytes(StandardCharsets.UTF_8));
526	            StringBuilder sb = new StringBuilder(digest.length * 2);
527	            for (byte b : digest) {
528	                sb.append(String.format("%02X", b));
529	            }
530	            return sb.substring(0, length);
531	        }
532	        catch (NoSuchAlgorithmException e) {
533	            throw new IllegalStateException(e);
534	        }
535	    }
536	
537	    /**
538	     * Count the existing owners located in the given city, compared case-insensitively.
539	     * Used to derive the per-city 4-digit sequence in the customer code.
540	     */
541	    private int countOwnersInCity(String city) {
542	        return (int) this.clinicService.findAllOwners().stream()
543	            .filter(existing -> existing.getCity() != null
544	                && existing.getCity().equalsIgnoreCase(city))
545	            .count();
546	    }
547	
548	    /**
549	     * Count the existing owners whose registration date is the given (adjusted business) date.
550	     * Used to enforce the per-day sign-up limit.
551	     */
552	    private int countOwnersRegisteredOn(LocalDate date) {
553	        return (int) this.clinicService.findAllOwners().stream()
554	            .filter(existing -> date.equals(existing.getRegistrationDate()))
555	            .count();
556	    }
557	
558	    /**
559	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
560	     * the following Monday; a weekday is returned unchanged.
561	     */
562	    private static LocalDate toBusinessDay(LocalDate date) {
563	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
564	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
565	            date = date.plusDays(1);
566	        }
567	        return date;
568	    }
569	
570	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
571	    @Override
572	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
573	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
574	        if (currentOwner == null) {
575	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
576	        }
577	        if (!normalizeEmail(ownerFieldsDto)) {
578	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
579	        }
580	        if (!normalizePostcode(ownerFieldsDto)) {
581	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
582	        }
583	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
584	        if (normalizedTelephone == null) {
585	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
586	        }
587	        currentOwner.setAddress(ownerFieldsDto.getAddress());
588	        currentOwner.setCity(ownerFieldsDto.getCity());
589	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
590	        currentOwner.setLastName(ownerFieldsDto.getLastName());
591	        currentOwner.setTelephone(normalizedTelephone);
592	        currentOwner.setEmail(ownerFieldsDto.getEmail());
593	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
594	        this.clinicService.saveOwner(currentOwner);
595	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
596	    }
597	
598	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
599	    @Transactional
600	    @Override
601	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
602	        Owner owner = this.clinicService.findOwnerById(ownerId);
603	        if (owner == null) {
604	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
605	        }
606	        this.clinicService.deleteOwner(owner);
607	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
608	    }
609	
610	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
611	    @Override
612	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
613	        Owner owner = this.clinicService.findOwnerById(ownerId);
614	        if (owner == null) {
615	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
616	        }
617	        HttpHeaders headers = new HttpHeaders();
618	        Pet pet = petMapper.toPet(petFieldsDto);
619	        owner.setId(ownerId);
620	        pet.setOwner(owner);
621	        pet.getType().setName(null);
622	        this.clinicService.savePet(pet);
623	        PetDto petDto = petMapper.toPetDto(pet);
624	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
625	            .buildAndExpand(pet.getId()).toUri());
626	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
627	    }
628	
629	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
630	    @Override
631	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
632	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
633	        if (currentOwner != null) {
634	            Pet currentPet = this.clinicService.findPetById(petId);
635	            if (currentPet != null) {
636	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
637	                currentPet.setName(petFieldsDto.getName());
638	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
639	                this.clinicService.savePet(currentPet);
640	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
641	            }
642	        }
643	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
644	    }
