647	    @Override
648	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
649	        HttpHeaders headers = new HttpHeaders();
650	        Visit visit = visitMapper.toVisit(visitFieldsDto);
651	        Pet pet = new Pet();
652	        pet.setId(petId);
653	        visit.setPet(pet);
654	        this.clinicService.saveVisit(visit);
655	        VisitDto visitDto = visitMapper.toVisitDto(visit);
656	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
657	            .buildAndExpand(visit.getId()).toUri());
658	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
