661	
662	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
663	    @Override
664	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
665	        Owner owner = this.clinicService.findOwnerById(ownerId);
666	        if (owner != null) {
667	            Pet pet = owner.getPet(petId);
668	            if (pet != null) {
669	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
670	            }
671	        }
672	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
673	    }
